import{_ as e,o as t,c as r,aA as o}from"./chunks/framework.BMzE2Z9R.js";const u=JSON.parse('{"title":"学习资源链接","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"nars/theory/learning_resources.md","filePath":"nars/theory/learning_resources.md","lastUpdated":1778399398000}'),l={name:"nars/theory/learning_resources.md"};function i(n,a,h,s,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="学习资源链接" tabindex="-1">学习资源链接 <a class="header-anchor" href="#学习资源链接" aria-label="Permalink to &quot;学习资源链接&quot;">​</a></h1><h2 id="_1-理论理解" tabindex="-1">1. 理论理解 <a class="header-anchor" href="#_1-理论理解" aria-label="Permalink to &quot;1. 理论理解&quot;">​</a></h2><h3 id="王培老师科普视频讲座" tabindex="-1">王培老师科普视频讲座 <a class="header-anchor" href="#王培老师科普视频讲座" aria-label="Permalink to &quot;王培老师科普视频讲座&quot;">​</a></h3><blockquote><p><strong>NARS 和 AGI 关键视频（50分钟） 1~5</strong></p></blockquote><p><a href="http://www.dushuren123.com/dushuren/video/share.html?id=1679351024" target="_blank" rel="noreferrer">《通用人工智能》（1）--王培 - 读书人 (dushuren123.com)</a></p><p>视频备份：<a href="https://space.bilibili.com/295431971/channel/seriesdetail?sid=1802789&amp;ctype=0" target="_blank" rel="noreferrer">破耳狼的个人空间-破耳狼个人主页-哔哩哔哩视频 (bilibili.com)</a></p><p>阅读后会对王培老师的理论有一个概览，NARS能做什么、AGI是什么，都会有一个答案。</p><h3 id="《智能理论纲要》" tabindex="-1">《智能理论纲要》 <a class="header-anchor" href="#《智能理论纲要》" aria-label="Permalink to &quot;《智能理论纲要》&quot;">​</a></h3><p>对理解的完整性，首推《智能论纲要》， 上海科技教育出版社，2022年09月</p><h3 id="基础概念相关中文文章和视频" tabindex="-1">基础概念相关中文文章和视频 <a class="header-anchor" href="#基础概念相关中文文章和视频" aria-label="Permalink to &quot;基础概念相关中文文章和视频&quot;">​</a></h3><p><a href="https://cis.temple.edu/~pwang/Chinese.html" target="_blank" rel="noreferrer">王培老师主页中文资料集</a></p><h3 id="王培老师对agi研究者的学习路径建议" tabindex="-1">王培老师对AGI研究者的学习路径建议 <a class="header-anchor" href="#王培老师对agi研究者的学习路径建议" aria-label="Permalink to &quot;王培老师对AGI研究者的学习路径建议&quot;">​</a></h3><blockquote><p>本资料原文为英文，推荐读完中文资料后再阅读 <a href="https://cis.temple.edu/~pwang/AGI-Curriculum.html" target="_blank" rel="noreferrer">AGI Education (temple.edu)</a></p></blockquote><details class="callout" data-callout="warning" data-callout-fold="+" open><summary class="callout-title"><div class="callout-title-icon"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-alert-triangle"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><path d="M12 9v4"></path><path d="M12 17h.01"></path></svg></div><div class="callout-title-inner">王培老师的备注</div><div class="callout-fold"></div></summary><div class="callout-content"><p></p><p>以下列表是对通用人工智能研究感兴趣的学生的部分教育计划。它包括大约25门一学期课程的材料。</p><p>笔记：</p><p>这里表达的意见是高度个人化的。不仅主题和阅读材料是根据我的意见选择的，还包括我自己的作品（它们用方括号与其他作品区分开来）。</p><p>这份清单并不打算涵盖所有相关主题，而是我认为最重要的主题。一些关键的决定是不包括什么，以及如何在主题之间分配时间。因此，在列表中添加新主题并不总是一个好主意。</p></div></details><p>在内容上大致分为：</p><h4 id="_1-介绍性读物" tabindex="-1">1. 介绍性读物 <a class="header-anchor" href="#_1-介绍性读物" aria-label="Permalink to &quot;1. 介绍性读物&quot;">​</a></h4><p>图灵的一篇论文、侯世达的《哥德尔、艾舍尔、巴赫：集异璧之大成》（王培老师为译者之一）。首先指出AI目标，然后指出智能的现象。集异璧(GEB)。</p><h4 id="_2-todo" tabindex="-1">2. (TODO) <a class="header-anchor" href="#_2-todo" aria-label="Permalink to &quot;2. (TODO)&quot;">​</a></h4><h2 id="_2-编码实现" tabindex="-1">2. 编码实现 <a class="header-anchor" href="#_2-编码实现" aria-label="Permalink to &quot;2. 编码实现&quot;">​</a></h2><p>参见<a href="./../impl/">NARS 各个版本实现介绍</a></p><h2 id="christian-g-hahm-ccrock4t-nars-python-v0-3" tabindex="-1">Christian G. Hahm（ccrock4t）NARS Python v0.3 <a class="header-anchor" href="#christian-g-hahm-ccrock4t-nars-python-v0-3" aria-label="Permalink to &quot;Christian G. Hahm（ccrock4t）NARS Python v0.3&quot;">​</a></h2><p>里面有一份图指南。</p>',22)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
